    ["Alliance Wins"] = "Перемога Альянсу",
    ["Allied Wristguard of Companionship"] = "Союзницькі Наручі Товариства",
    ["Allow render scale to be dynamically changed to help hit a Target FPS."] = "Дозволяє динамічно змінювати масштаб рендерингу, щоб досягати цільового FPS.",
    ["Allows asynchronously creating GPU resources such as textures and shaders. Disabling this will likely introduce hitching but could help work around crashes or visual issues on very old drivers or hardware."] = "Дозволяє асинхронно створювати ресурси GPU, як-от текстури та шейдери. Вимкнення, найімовірніше, спричинить підвисання, але може допомогти обійти збої чи візуальні негаразди на дуже старих драйверах або обладнанні.",
    ["Allows enabling transcription on a voice channel in order to see written text based on the words spoken by other players"] = "Дозволяє ввімкнути транскрипцію на голосовому каналі, щоб бачити текст, набраний зі слів, які промовляють інші гравці",
    ["Allows for the transmission of voice chat by just speaking."] = "Дозволяє передавати голос у чаті просто розмовляючи.",
    ["Allows friends and guild members to instantly join your queues without a confirmation."] = "Дозволяє друзям і членам гільдії миттєво приєднуватися до ваших черг без підтвердження.",
    ["Allows more complex code paths for submitting work to the GPU. Disabling this may cause less consistent or lower framerate but could help avoid some kinds of crashes for certain hardware, driver and OS combinations."] = "Дозволяє складніші способи передавання завдань на графічний процесор. Вимкнення може спричинити нерівномірну або нижчу частоту кадрів, але здатне допомогти уникнути деяких збоїв на певних поєднаннях обладнання, драйверів та операційної системи.",
    ["Allows more complex code paths for submitting work to the GPU. Disabling this may cause less consistent or lower framerate but could help avoid some kinds of crashes for certain hardware, driver and OS combinations. "] = "Дозволяє складніші шляхи коду для передавання роботи відеокарті. Вимкнення може знизити чи зробити менш стабільною частоту кадрів, але інколи допомагає уникнути збоїв на певних комбінаціях обладнання, драйверів і ОС. ",
    ["Allows the CPU to work on 2 frames at once. Disabling this may cause less consistent or lower framerate but could help avoid some kinds of crashes for certain hardware, driver and OS combinations."] = "Дозволяє процесору одночасно обробляти 2 кадри. Вимкнення може спричинити нерівномірну або нижчу частоту кадрів, але здатне допомогти уникнути деяких збоїв на певних поєднаннях обладнання, драйверів та операційної системи.",
    ["Allows the CPU to work on 2 frames at once. Disabling this may cause less consistent or lower framerate but could help avoid some kinds of crashes for certain hardware, driver and OS combinations. "] = "Дозволяє процесору опрацьовувати 2 кадри водночас. Вимкнення може знизити чи зробити менш стабільною частоту кадрів, але інколи допомагає уникнути збоїв на певних комбінаціях обладнання, драйверів і ОС. ",
    ["Allows the game to use multiple CPU threads to render the game. Disabling this will likely greatly reduce framerate, but could work around crashes or visual bugs in some cases."] = "Дозволяє грі використовувати кілька потоків процесора для рендерингу. Вимкнення, найімовірніше, значно знизить частоту кадрів, але в деяких випадках може обійти збої чи графічні помилки.",
    ["Allows the game to use multiple CPU threads to render the game. Disabling this will likely greatly reduce framerate, but could work around crashes or visual bugs in some cases. "] = "Дозволяє грі використовувати кілька потоків процесора для рендерингу. Вимкнення, найімовірніше, суттєво знизить частоту кадрів, але інколи допомагає обійти збої чи візуальні помилки. ",
    ["Allows the game to use various techniques to reduce input latency"] = "Дозволяє грі застосовувати різні методи для зменшення затримки введення",
    ["Allows the use of newer GPU features. When disabled, the game will act as if the GPU only supports the minimum required features. Various graphical features will be disabled and the visual quality of the game will likely be reduced. This may help work around driver bugs or other issues with newer GPU features."] = "Дозволяє використовувати новіші можливості графічного процесора. Коли вимкнено, гра поводитиметься так, ніби процесор підтримує лише мінімально потрібні функції. Різні графічні можливості буде вимкнено, і якість зображення, найімовірніше, знизиться. Це може допомогти обійти помилки драйверів або інші проблеми з новішими можливостями графічного процесора.",
    ["Allows you to change the primary monitor used by the display."] = "Дозволяє змінити основний монітор, що використовується для відображення.",
    ["Allows you to interact with NPCs and objects using a keypress"] = "Дозволяє взаємодіяти з NPC та об'єктами натисканням клавіші",
    ["Allows you to reduce the time before a Global Cooldown has finished during which you may queue up a spell. You may want to set this to approximate your latency."] = "Дозволяє скоротити проміжок перед завершенням глобального перезарядження, протягом якого можна поставити закляття в чергу. Варто встановити значення, приблизно рівне вашій затримці.",
    ["Allows you to resize, reposition, collapse and expand the Objectives frame."] = "Дозволяє змінювати розмір, переміщувати, згортати та розгортати панель цілей.",
