    ["Always display the text on your character's health, mana, rage, or energy bars."] = "Завжди показувати текст на смужках здоров'я, мани, люті чи енергії вашого персонажа.",
    ["Always display the text on your party's health, mana, rage, or energy bars."] = "Завжди показувати текст на смужках здоров'я, мани, люті чи енергії вашої групи.",
