    ["Check All"] = "Позначити всі",
    ["Check this box to override your language setting and use english audio."] = "Позначте, щоб знехтувати налаштуванням мови та використовувати англійський звук.",
    ["Check this option to always display extra actionbars."] = "Позначте цей параметр, щоб завжди показувати додаткові панелі дій.",
    ["Check this option to automatically join the Guild Recruitment chat channel based upon whether or not you are in a guild."] = "Позначте цей параметр, щоб автоматично приєднуватися до каналу набору до гільдії залежно від того, чи перебуваєте ви в гільдії.",
    ["Check this to enable dynamic reduction of terrain polygon detail.  Check to increase performance."] = "Позначте, щоб увімкнути динамічне зниження деталізації полігонів місцевості. Позначте, щоб підвищити продуктивність.",
    ["Check this to make quest text appear instantly."] = "Позначте, щоб текст завдання з'являвся миттєво.",
    ["Check this to rotate the entire minimap instead of the player arrow."] = "Позначте, щоб обертати всю мінікарту замість стрілки гравця.",
    ["Check this to show a number countdown for action button cooldowns."] = "Позначте, щоб показувати числовий відлік перезарядження кнопок дій.",
    ["Check this to show threat on targets as a percentage."] = "Позначте, щоб показувати загрозу на цілях у відсотках.",
    ["Check this to use higher definition character models."] = "Позначте, щоб використовувати моделі персонажів вищої чіткості.",
    ["Check to enable integration of WoW with Twitter. Tweet with Twitter using /share"] = "Позначте, щоб увімкнути інтеграцію WoW із Twitter. Публікуйте твіти в Twitter за допомогою /share",
    ["Check to make the mouse wheel scroll through chat when the cursor is over a chat window."] = "Позначте, щоб коліщатко миші прокручувало чат, коли курсор перебуває над вікном чату.",
    ["Check to maximize window and remove borders."] = "Позначте, щоб розгорнути вікно й прибрати рамки.",
    ["Check to play in a non-fullscreen window.\n\nIf this is checked the game will use your desktop gamma and you will not be able to adjust it via the slider below."] = "Позначте, щоб грати у вікні (не на весь екран).\n\nЯкщо позначено, гра використовуватиме гаму вашого робочого стола, і ви не зможете налаштувати її повзунком нижче.",
    ["Check to show chat windows immediately upon mouseover."] = "Позначте, щоб вікна чату з'являлися одразу при наведенні миші.",
    ["Check to use the UI Scale Slider, uncheck to use the system default scale."] = "Позначте, щоб використовувати повзунок масштабу інтерфейсу; зніміть позначку, щоб використовувати типовий системний масштаб.",
    ["Checking this will enable additional combat messages to appear in pet battles."] = "Позначення увімкне показ додаткових бойових повідомлень у битвах улюбленців.",
    ["Checking this will enable additional combat messages to appear in the playfield."] = "Позначення увімкне показ додаткових бойових повідомлень на ігровому полі.",
    ["Checking this will hide the interface for tracking zone wide objectives."] = "Позначення приховає інтерфейс відстеження цілей по всій зоні.",
    ["Checking this will prevent the deselection of targets by clicking on the gamefield.  Targets can only be cleared by pressing escape or clicking another target."] = "Позначення завадить знімати вибір цілі кліком по ігровому полю. Ціль можна скинути лише натисканням Escape або вибором іншої цілі.",
