    ["Compatibility settings are offered to help diagnose and work around various crashes, graphical bugs and performance issues. In most cases disabling these features will decrease performance, introduce hitching and/or decrease visual quality. They are only intended to be disabled if you are having specific issues."] = "Налаштування сумісності пропонуються, щоб допомогти діагностувати й обійти різні збої, графічні баги та проблеми з продуктивністю. У більшості випадків вимкнення цих функцій знизить продуктивність, спричинить ривки та/або погіршить якість зображення. Їх варто вимикати лише за наявності конкретних проблем.",
