    ["Conquest Hold"] = "Форт Підкорення",
    ["Conservative Morphological Anti-Aliasing 2: More advanced version of CMAA (preferred method if also using \"Multisample Techniques\")."] = "Conservative Morphological Anti-Aliasing 2: удосконалена версія CMAA (бажаний метод, якщо ви також використовуєте «Multisample Techniques»).",
    ["Conservative Morphological Anti-Aliasing: Even more precise calculations for a variety of edge-detection techniques to blur edges."] = "Conservative Morphological Anti-Aliasing: ще точніші обчислення для різних методів виявлення країв, щоб згладжувати їх.",
