    ["Containment Core"] = "Стримувальне ядро",
    ["Contender's Dragonscale Helm"] = "Шолом Суперника з Драконячої Луски",
    ["Contender's Dragonscale Shoulders"] = "Наплічники Суперника з Драконячої Луски",
    ["Contender's Leather Helm"] = "Шкіряний Шолом Суперника",
    ["Contender's Scale Chestguard"] = "Лусковий нагрудник Суперника",
    ["Contender's Scale Helm"] = "Лусковий шолом Суперника",
    ["Contender's Wyrmhide Chestguard"] = "Нагрудник Суперника зі шкіри вірма",
    ["Contender's Wyrmhide Helm"] = "Шолом Суперника зі шкіри вірма",
    ["Contract: The Hara'ti"] = "Контракт: Гара'ті",
    ["Contracts"] = "Контракти",
    ["Contrast"] = "Контраст",
    ["Control real-time chat moderation notifications for potentially inappropriate sent and received messages."] = "Керує сповіщеннями модерації чату в реальному часі про потенційно недоречні надіслані та отримані повідомлення.",
    ["Controls both the method and quality of lighting.  Decreasing this may improve performance."] = "Керує методом і якістю освітлення. Зменшення може підвищити продуктивність.",
    ["Controls both the method and quality of shadows. Decreasing this may greatly improve performance."] = "Керує методом і якістю тіней. Зменшення може значно підвищити продуктивність.",
    ["Controls how far you can see objects. Decrease to improve performance."] = "Керує тим, як далеко ви бачите об'єкти. Зменшіть, щоб підвищити продуктивність.",
    ["Controls how notch overlap is handled"] = "Керує тим, як обробляється перекриття вирізом екрана",
    ["Controls how the Light Radius Indicator is displayed on non-selected Decor while decorating."] = "Керує тим, як показується індикатор радіуса світла на невибраному декорі під час оздоблення.",
    ["Controls how the Light Radius Indicator is displayed on selected Decor while decorating."] = "Керує тим, як показується індикатор радіуса світла на вибраному декорі під час оздоблення.",
    ["Controls how the dispel indicator icons are shown, this is separate from the debuff display."] = "Керує тим, як показуються значки індикатора розвіювання; це окремо від показу послаблень.",
    ["Controls intensity of Variable Rate Shading (VRS) features. VRS is a GPU hardware feature that reduces the GPU workload without significantly reducing visual quality. Enabling this feature on supported hardware may improve FPS."] = "Керує інтенсивністю функцій Variable Rate Shading (VRS). VRS — це апаратна функція відеокарти, яка зменшує навантаження на GPU без істотного погіршення якості зображення. Увімкнення цієї функції на підтримуваному обладнанні може підвищити FPS.",
    ["Controls the Brightness of the game."] = "Керує яскравістю гри.",
    ["Controls the Contrast of the game."] = "Керує контрастністю гри.",
    ["Controls the Gamma of the game."] = "Керує гамою гри.",
    ["Controls the density and the distance at which ground clutter items, like grass and foliage, are placed. Decrease to improve performance."] = "Керує щільністю та відстанню розміщення дрібних об'єктів на землі, як-от трава й рослинність. Зменшіть, щоб підвищити продуктивність.",
    ["Controls the detail level of spell effects. Decrease to improve performance."] = "Керує рівнем деталізації ефектів заклять. Зменшіть, щоб підвищити продуктивність.",
    ["Controls the draw distance of ground clutter items like grass and foliage. Decrease to improve performance."] = "Керує відстанню промальовування дрібних об'єктів на землі, як-от трава й рослинність. Зменшіть, щоб підвищити продуктивність.",
    ["Controls the intensity of weather effects. Decrease to improve performance."] = "Керує інтенсивністю погодних ефектів. Зменшіть, щоб підвищити продуктивність.",
    ["Controls the level of all texture detail. Decreasing this may slightly improve performance."] = "Керує рівнем деталізації всіх текстур. Зменшення може трохи підвищити продуктивність.",
    ["Controls the method and quality used to display sunshaft and glare effects. Disabling this setting may improve performance."] = "Керує способом і якістю відображення ефектів сонячних променів та відблисків. Вимкнення цього налаштування може підвищити продуктивність.",
    ["Controls the number of ground clutter items, like grass and foliage. Decrease to improve performance."] = "Керує кількістю дрібних об'єктів на землі, як-от трава й рослинність. Зменшіть, щоб підвищити продуктивність.",
    ["Controls the number of particles used in effects caused by spells, fires, etc. Decrease to improve performance."] = "Керує кількістю частинок в ефектах від заклять, вогню тощо. Зменшіть, щоб підвищити продуктивність.",
    ["Controls the quality of Compute-based effects such as Volumetric Fog and some particle effects. Compute-based effects may be more expensive for older graphics cards."] = "Керує якістю обчислювальних ефектів, як-от об'ємний туман та деякі ефекти частинок. Обчислювальні ефекти можуть бути затратнішими для старіших відеокарт.",
    ["Controls the rendering of depth-based particle effects.  Decreasing this may improve performance."] = "Керує відтворенням ефектів частинок на основі глибини. Зменшення може підвищити продуктивність.",
    ["Controls the rendering quality of liquid. Decreasing this may improve performance."] = "Керує якістю відтворення рідини. Зменшення може підвищити продуктивність.",
    ["Controls the rendering quality of the advanced lighting effects. Decreasing this may greatly improve performance."] = "Керує якістю відтворення розширених ефектів освітлення. Зменшення може значно підвищити продуктивність.",
    ["Controls the resolution of player textures. Decreasing this may slightly improve performance."] = "Керує роздільною здатністю текстур гравців. Зменшення може трохи підвищити продуктивність.",
    ["Controls visibility of non-essential spells."] = "Керує видимістю другорядних заклять.",
    ["Controls whether or not icon links in auto-joined chat channels (such as Trade) are displayed as icons."] = "Керує тим, чи відображати посилання на іконки у каналах чату з автоматичним приєднанням (як-от Торгівля) у вигляді іконок.",
    ["Controls whether the selection outline effect is allowed.  See the Interface Display panel for more options."] = "Керує тим, чи дозволено ефект обведення вибраного. Більше параметрів дивіться на панелі відображення інтерфейсу.",
    ["Controls which icons appear above NPCs and objects when the Interact Key feature is enabled"] = "Керує тим, які іконки з'являються над NPC та об'єктами, коли увімкнено функцію клавіші взаємодії",
