    ["Display a number only when health is lost"] = "Показувати число лише при втраті здоров'я",
    ["Display amount of healing you did to the target."] = "Показувати обсяг зцілення, яке ви надали цілі.",
    ["Display amount of shield you added to the target."] = "Показувати обсяг щита, який ви додали цілі.",
    ["Display an in-world marker indicating the direction and distance of a tracked quest or waypoint."] = "Показувати у світі позначку напрямку та відстані до відстежуваного завдання чи дороговказу.",
    ["Display any debuffs on your party members"] = "Показувати будь-які послаблення на учасниках вашої групи",
    ["Display bars for mana, energy, rage, etc. on the raid frames."] = "Показувати смужки мани, енергії, люті тощо на рамках рейду.",
    ["Display border artwork around the Raid Frames."] = "Показувати оздоблення рамок навколо рамок рейду.",
    ["Display class specific colors. If unchecked, default colors will be used."] = "Показувати кольори, властиві класам. Якщо вимкнено, використовуються типові кольори.",
    ["Display class specific colors. If unchecked, default role colors will be used."] = "Показувати кольори, властиві класам. Якщо вимкнено, використовуються типові кольори ролей.",
    ["Display damage caused by periodic effects such as Rend and Shadow Word: Pain."] = "Показувати шкоду від періодичних ефектів, як-от Роздирання та Слово в Тінь: Біль.",
    ["Display damage numbers over hostile creatures when damaged."] = "Показувати числа шкоди над ворожими істотами, коли їм завдають шкоди.",
    ["Display effects such as Silence and Snare on other players' targets."] = "Показувати ефекти, як-от Німота та Пастка, на цілях інших гравців.",
    ["Display effects such as Silence and Snare on your target."] = "Показувати ефекти, як-от Німота та Пастка, на вашій цілі.",
    ["Display heals currently in the process of being cast."] = "Показувати зцілення, яке наразі твориться.",
    ["Display important defensive buffs as a large icon in the center of the unit frame"] = "Показувати важливі захисні підсилення великою іконкою в центрі рамки істоти",
    ["Display incoming heals on your party members"] = "Показувати вхідне зцілення на учасниках вашої групи",
    ["Display item level in the tooltip for certain items."] = "Показувати рівень предмета в підказці для певних предметів.",
    ["Display only debuffs which you are capable of removing from a target."] = "Показувати лише ті послаблення, які ви здатні зняти з цілі.",
    ["Display only dispellable debuffs on your party members"] = "Показувати лише послаблення, які можна розвіяти, на учасниках вашої групи",
    ["Display only healer power bars. Non-healer power bars will be hidden."] = "Показувати смуги ресурсу лише цілителів. Смуги ресурсу нецілителів будуть приховані.",
    ["Display raid members' pets in the Raid Frame interface."] = "Показувати улюбленців учасників рейду в інтерфейсі рамок рейду.",
    ["Display red outline if player has aggro"] = "Показувати червоний контур, якщо гравець утримує загрозу",
    ["Display remaining health as a number"] = "Показувати залишок здоров'я числом",
    ["Display remaining health as a percentage"] = "Показувати залишок здоров'я у відсотках",
    ["Display role-specific debuffs slightly larger than other debuffs"] = "Показувати послаблення, пов'язані з роллю, трохи більшими за інші послаблення",
    ["Display separate frames for each group in your raid."] = "Показувати окремі рамки для кожної групи у вашому рейді.",
    ["Display special unit frames for players your raid leader has marked as \"Main Tank\" or \"Main Assist\"."] = "Показувати особливі рамки істот для гравців, яких лідер рейду позначив як «Головний танк» або «Головний помічник».",
    ["Display status text as numbers, percentage, or both."] = "Показувати текст стану числами, у відсотках або обома способами.",
    ["Display the power bars of pvp opponents"] = "Показувати смуги ресурсу суперників у PvP",
    ["Display the power bars of your party members"] = "Показувати смуги ресурсу учасників вашої групи",
    ["Display the summoned pets of your pvp opponents."] = "Показувати викликаних улюбленців ваших суперників у PvP.",
    ["Display the summoned pets of your raid and party members"] = "Показувати викликаних улюбленців учасників вашого рейду та групи",
    ["Display tutorials which help introduce you to WoW."] = "Показувати навчальні підказки, які допоможуть ознайомитися з WoW.",
    ["Display unit names in the game world."] = "Показувати імена істот у світі гри.",
    ["Display your character's name in the game world."] = "Показувати ім'я вашого персонажа у світі гри.",
    ["Displays a Blizzard message when a Real ID or BattleTag friend comes online."] = "Показує повідомлення Blizzard, коли друг за Real ID або BattleTag заходить у гру.",
    ["Displays a Blizzard message when a Real ID or BattleTag friend goes offline."] = "Показує повідомлення Blizzard, коли друг за Real ID або BattleTag виходить із гри.",
    ["Displays a Blizzard message when a Real ID or BattleTag friend updates their broadcast."] = "Показує повідомлення Blizzard, коли друг за Real ID або BattleTag оновлює своє оголошення.",
