    ["Enable Sound"] = "Увімкнути звук",
    ["Enable Text Warnings"] = "Текстові попередження",
    ["Enable UI Colorblind Mode"] = "Режим для дальтоніків (інтерфейс)",
    ["Enable Voice"] = "Увімкнути голос",
    ["Enable ambient sounds."] = "Увімкнути навколишні звуки.",
    ["Enable background music."] = "Увімкнути фонову музику.",
    ["Enable detailed tooltips in the lower right hand corner of the screen."] = "Увімкнути докладні підказки в нижньому правому куті екрана.",
    ["Enable mature language filtering."] = "Увімкнути фільтрування ненормативної лексики.",
    ["Enable special music during pet battles."] = "Увімкнути особливу музику під час битв улюбленців.",
    ["Enable the playing of alert sounds when aggro advances to a higher level."] = "Увімкнути відтворення сповіщальних звуків, коли загроза зростає до вищого рівня.",
    ["Enable this option for a more responsive cursor unless you have cursor problems."] = "Увімкніть цю опцію для чутливішого курсора, якщо у вас немає проблем із курсором.",
    ["Enable this option for smooth lighting across characters."] = "Увімкніть цей параметр для плавного освітлення на персонажах.",
    ["Enable this option if you have a World of Warcraft Gaming Mouse and you wish to bind keys to the extra buttons."] = "Увімкніть цей параметр, якщо у вас є ігрова миша World of Warcraft і ви хочете призначити клавіші на додаткові кнопки.",
    ["Enable this option to optimize network usage for speed in order to decrease lag.\nThis will increase your bandwidth usage, and may cause problems in some environments. Disabling this option may help resolve certain disconnection issues."] = "Увімкніть цей параметр, щоб оптимізувати використання мережі заради швидкості та зменшити затримку.\nЦе збільшить використання вашого каналу зв'язку й може спричинити проблеми в деяких середовищах. Вимкнення цього параметра може допомогти усунути певні проблеми з розривами з'єднання.",
    ["Enable this to have Blizzard system messages appear in a popup window."] = "Увімкніть, щоб системні повідомлення Blizzard з'являлися у спливному вікні.",
    ["Enable this to prevent resizing the game window."] = "Увімкніть, щоб заборонити зміну розміру вікна гри.",
    ["Enable to allow sounds to play even when World of Warcraft is in the background."] = "Увімкніть, щоб дозволити відтворення звуків навіть тоді, коли World of Warcraft працює у фоновому режимі.",
    ["Enable to continuously play background music."] = "Увімкніть, щоб безперервно відтворювати фонову музику.",
    ["Enables Light Radius Indicators to show when placing Decor"] = "Вмикає показ покажчиків радіуса освітлення під час розміщення оздоблення.",
    ["Enables a full screen effect that softens edges and lighting. Disabling this can sometimes improve performance."] = "Вмикає повноекранний ефект, що пом'якшує краї та освітлення. Вимкнення цього іноді може покращити продуктивність.",
    ["Enables all pixel shaders."] = "Вмикає всі піксельні шейдери.",
    ["Enables character shadows for all characters within the game.  Disabling this can sometimes improve performance."] = "Вмикає тіні для всіх персонажів у грі.  Вимкнення цього іноді може покращити продуктивність.",
    ["Enables extra logging data when writing the combat log to a text file. This may cause additional network lag when using the \"combatlog\" chat command."] = "Вмикає запис додаткових даних під час збереження журналу бою в текстовий файл. Це може спричинити додаткову мережеву затримку під час використання чат-команди \"combatlog\".",
    ["Enables high quality filtering of texture maps. Turn this feature off to increase performance."] = "Вмикає високоякісну фільтрацію текстур. Вимкніть цю функцію, щоб підвищити продуктивність.",
    ["Enables highlights that suggest the ability to use.|nThe Assisted Highlight will only suggest visible abilities."] = "Вмикає підсвічування, що підказує, яку здібність застосувати.|nДопоміжне підсвічування підказує лише видимі здібності.",
    ["Enables or disables all dialog."] = "Вмикає або вимикає всі діалоги.",
    ["Enables or disables all sound."] = "Вмикає або вимикає весь звук.",
    ["Enables or disables game sound effects."] = "Вмикає або вимикає звукові ефекти гри.",
    ["Enables reverb sound effects. This will affect performance."] = "Вмикає ефекти реверберації звуку. Це вплине на продуктивність.",
    ["Enables setting a custom mouse sensitivity to override the setting from the operating system."] = "Дозволяє встановити власну чутливість миші замість значення з операційної системи.",
    ["Enables specular highlights on terrain. Disabling this can sometimes improve performance."] = "Вмикає дзеркальні відблиски на ландшафті. Вимкнення цього іноді може покращити продуктивність.",
    ["Enables speech from errors (e.g. \"Target out of range\")."] = "Вмикає озвучення помилок (наприклад, \"Ціль поза межами досяжності\").",
    ["Enables speech from groupmates."] = "Вмикає озвучення повідомлень від учасників групи.",
    ["Enables stereoscopic (3D) video."] = "Вмикає стереоскопічне (3D) зображення.",
    ["Enables subtitles during cinematics."] = "Вмикає субтитри під час кінематографічних роликів.",
    ["Enables the projecting of textures to the environment. Disabling this may improve performance."] = "Вмикає проєктування текстур на оточення. Вимкнення цього може покращити продуктивність.",
    ["Enables the use of IPv6, the technology behind the next-generation Internet.\nRequires IPv6 connectivity to the Internet.  Checking this box without IPv6 connectivity may prevent you from playing WoW."] = "Вмикає використання IPv6 — технології, що лежить в основі Інтернету наступного покоління.\nПотребує з'єднання з Інтернетом через IPv6.  Установлення цього прапорця без підтримки IPv6 може завадити вам грати у WoW.",
    ["Enables the use of hardware for 3D sound management. This may alter your sound performance."] = "Вмикає використання апаратного забезпечення для керування 3D-звуком. Це може змінити продуктивність звуку.",
    ["Enables the use of vertex shaders to speed animation. Enable this to maximize performance."] = "Вмикає використання вершинних шейдерів для прискорення анімації. Увімкніть це, щоб досягти максимальної продуктивності.",
    ["Enables typing into the voice chat window to speak to other players using the selected voice"] = "Дозволяє вводити текст у вікні голосового чату, щоб говорити з іншими гравцями обраним голосом.",
    ["Enables your microphone."] = "Вмикає ваш мікрофон.",
    ["Enabling the Motion Sickness setting will reduce camera movement and keep your character centered."] = "Увімкнення параметра захисту від заколисування зменшить рух камери й утримуватиме вашого персонажа в центрі.",
    ["Enabling this option will also display Blizzard messages in a toast window."] = "Увімкнення цього параметра також показуватиме повідомлення Blizzard у спливному сповіщенні.",
    ["Enabling this reduces user interface lag, but may drastically reduce frame rates."] = "Увімкнення цього зменшує затримку інтерфейсу, але може суттєво знизити частоту кадрів.",
