    ["Icons in Chat"] = "Значки в чаті",
    ["If checked, Clean Up Bags will move items to your rightmost bags."] = "Якщо позначено, «Упорядкувати сумки» переміщатиме речі до ваших найправіших сумок.",
    ["If checked, new items will appear in your leftmost bag."] = "Якщо позначено, нові речі з'являтимуться у вашій найлівішій сумці.",
    ["If checked, uses normal turn controls when reversing during Drive."] = "Якщо позначено, під час руху назад у режимі їзди використовуються звичайні елементи керування поворотом.",
    ["If enabled while using Move Forward and Move Backward to control pitch, this setting will require those inputs to be pressed again when transitioning between grounded and skyriding."] = "Якщо ввімкнено під час керування нахилом за допомогою «Уперед» і «Назад», цей параметр вимагатиме повторного натискання цих клавіш під час переходу між пересуванням по землі та небесною їздою.",
    ["If enabled while using Move Forward and Move Backward to control pitch, this setting will require those inputs to be pressed again when transitioning between grounded and skyriding. "] = "Якщо ввімкнено й ви керуєте нахилом через Рух вперед і Рух назад, ці клавіші доведеться натиснути знову під час переходу між землею та небесною їздою. ",
    ["If enabled, allows the player to press and hold a keyboard hotkey to continually cast a spell on an ActionBar without having to repeatedly press the button. This only supports keyboard hotkeys, clicking a spell with the mouse will still cast the spell a single time."] = "Якщо ввімкнено, дозволяє гравцеві натиснути й утримувати клавішу швидкого доступу, щоб безперервно творити закляття на панелі дій без повторних натискань кнопки. Підтримуються лише клавіші швидкого доступу; клацання закляття мишею все одно сотворить його лише раз.",
    ["If enabled, you will be able to look at your map to see the locations of certain quest objectives."] = "Якщо ввімкнено, ви зможете дивитися на карту, щоб бачити розташування певних цілей завдань.",
    ["If enabled, your character will automatically dismount before casting while flying."] = "Якщо ввімкнено, ваш персонаж автоматично спішуватиметься перед творенням закляття під час польоту.",
    ["If enabled, your character will automatically switch between auto attack and auto shot."] = "Якщо ввімкнено, ваш персонаж автоматично перемикатиметься між автоатакою та автопострілом.",
    ["If the Name Plate is displayed for your current target, show the enemy cast bar with the target's health bar in the game field."] = "Якщо для вашої поточної цілі показано табличка імен, відображати ворожу смугу творення закляття разом зі смугою здоров'я цілі в ігровому полі.",
