    ["Set View 5"] = "Задати ракурс 5",
    ["Set the camera to always prefer being behind your character."] = "Налаштувати камеру так, щоб вона завжди прагнула бути позаду вашого персонажа.",
    ["Set the camera to be above water when your character is above water, and below water when your character is below water."] = "Налаштувати камеру так, щоб вона була над водою, коли ваш персонаж над водою, і під водою, коли ваш персонаж під водою.",
    ["Set the camera to stay where placed, except when your character is moving."] = "Налаштувати камеру так, щоб вона залишалася на місці, окрім моментів, коли ваш персонаж рухається.",
    ["Set the camera to stay where placed, except when your character is moving. (only adjusts horizontal position)"] = "Налаштувати камеру так, щоб вона залишалася на місці, окрім моментів, коли ваш персонаж рухається. (змінює лише горизонтальне положення)",
    ["Set the camera to stay where set, and never auto adjust."] = "Налаштувати камеру так, щоб вона залишалася на встановленому місці й ніколи не підлаштовувалася автоматично.",
    ["Set the game to run in Fullscreen or Windowed mode."] = "Налаштувати запуск гри в повноекранному або віконному режимі.",
    ["Set the opacity of alerts that show in the center of your screen when certain important events occur."] = "Встановлює непрозорість сповіщень, що з'являються в центрі екрана, коли стаються певні важливі події.",
    ["Set your status:"] = "Встановити статус:",
    ["Sets Auto Looting as the default action when clicking on lootable things. (Looting when this is checked, or Auto Looting when it is not, is performed by holding the Loot Key / Auto Loot Key.)"] = "Робить автоматичний збір здобичі типовою дією при натисканні на об'єкти зі здобиччю. (Якщо позначено — звичайний збір, якщо ні — автоматичний збір, виконується утриманням клавіші збору / клавіші автозбору.)",
    ["Sets Target of Target to always display."] = "Завжди показувати ціль вашої цілі.",
    ["Sets Target of Target to display when solo."] = "Показувати ціль вашої цілі, коли ви граєте наодинці.",
    ["Sets Target of Target to display when you are in a party."] = "Показувати ціль вашої цілі, коли ви в групі.",
    ["Sets Target of Target to display when you are in a raid or a party."] = "Показувати ціль вашої цілі, коли ви в рейді або групі.",
    ["Sets Target of Target to display when you are in a raid."] = "Показувати ціль вашої цілі, коли ви в рейді.",
    ["Sets the Multisample Anti-Aliasing mode. Both the number of color and depth samples can be specified."] = "Встановлює режим багатовибіркового згладжування (MSAA). Можна вказати кількість як кольорових вибірок, так і вибірок глибини.",
    ["Sets the Post-Process Anti-Aliasing mode."] = "Встановлює режим постобробного згладжування.",
    ["Sets the camera to always be aligned with your character when changing direction with click-to-move."] = "Камера завжди вирівнюється за вашим персонажем при зміні напрямку рухом за вказівником миші.",
    ["Sets the camera to follow your character after a brief delay when changing direction with click-to-move. (Recommended Mode)"] = "Камера слідує за вашим персонажем із невеликою затримкою при зміні напрямку рухом за вказівником миші. (Рекомендований режим)",
    ["Sets the camera to follow your character after a brief delay when changing direction with click-to-move. (Recommended Mode) "] = "Камера слідує за персонажем із невеликою затримкою під час зміни напрямку через клік-для-руху. (Рекомендований режим) ",
    ["Sets the camera to not move when changing direction with click-to-move."] = "Камера не рухається при зміні напрямку рухом за вказівником миші.",
    ["Sets the direction that combat text scrolls."] = "Встановлює напрямок прокручування бойового тексту.",
    ["Sets the rate at which one type of terrain blends to another."] = "Встановлює швидкість, з якою один тип місцевості переходить в інший.",
    ["Sets the resolution of the game window."] = "Встановлює роздільність ігрового вікна.",
    ["Sets up a main chat window and a combat log that cannot be reconfigured."] = "Налаштовує головне вікно чату та бойовий журнал, які не можна переналаштувати.",
