    ["Show Unlearned"] = "Показати невивчені",
    ["Show Warband Completed Quests"] = "Показувати завдання, виконані бойовою ватагою",
    ["Show a background behind party members and enemy arena team members."] = "Показувати тло за учасниками групи та ворожими гравцями команди арени.",
    ["Show a message when your guild members login and logout."] = "Показувати повідомлення, коли учасники вашої гільдії входять у гру та виходять із неї.",
    ["Show additional options for color overrides."] = "Показувати додаткові параметри для перевизначення кольорів.",
    ["Show alerts when certain important events occur."] = "Показувати сповіщення, коли стаються певні важливі події.",
    ["Show all debuffs on enemy targets instead of just those deemed relevant to you."] = "Показувати всі послаблення на ворожих цілях, а не лише ті, що вважаються важливими для вас.",
    ["Show all dispel indicator types even if I can't dispel it"] = "Показувати всі типи позначок розвіювання, навіть якщо я не можу розвіяти цей ефект",
    ["Show cooldowns for important spells under your character"] = "Показувати перезарядження важливих заклять під вашим персонажем",
    ["Show critter and vanity pet names in the game world."] = "Показувати імена дрібних тварин та декоративних улюбленців в ігровому світі.",
    ["Show damage caused by your pet."] = "Показувати шкоду, завдану вашим улюбленцем.",
    ["Show enemy guardian names in the game world."] = "Показувати імена ворожих охоронців в ігровому світі.",
    ["Show enemy pet, guardian, and totem names in the game world."] = "Показувати імена ворожих улюбленців, охоронців і тотемів в ігровому світі.",
    ["Show enemy players' names in the game world."] = "Показувати імена ворожих гравців в ігровому світі.",
    ["Show enemy totem names in the game world."] = "Показувати імена ворожих тотемів в ігровому світі.",
    ["Show enemy unit frames in arenas."] = "Показувати рамки ворожих істот на аренах.",
    ["Show everything"] = "Показати все",
    ["Show friendly buffs under your character"] = "Показувати дружні підсилення під вашим персонажем",
    ["Show friendly guardian names in the game world."] = "Показувати імена дружніх охоронців в ігровому світі.",
    ["Show friendly pet, guardian, and totem names in the game world."] = "Показувати імена дружніх улюбленців, охоронців і тотемів в ігровому світі.",
    ["Show friendly players' names in the game world."] = "Показувати імена дружніх гравців в ігровому світі.",
    ["Show friendly totem names in the game world."] = "Показувати імена дружніх тотемів в ігровому світі.",
    ["Show information on spells, and interface."] = "Показувати інформацію про закляття та інтерфейс.",
    ["Show nameplates for enemy units"] = "Показувати таблички імен ворожих істот",
    ["Show nameplates for friendly players"] = "Показувати таблички імен дружніх гравців",
    ["Show on Backpack"] = "Показувати на наплічнику",
    ["Show only buffs you can cast on friendly targets."] = "Показувати лише підсилення, які ви можете накласти на дружні цілі.",
    ["Show only debuffs you can dispel on friendly targets."] = "Показувати лише ті послаблення на дружніх цілях, які ви можете розвіяти.",
    ["Show only the debuffs you applied on enemy targets."] = "Показувати лише ті послаблення на ворожих цілях, які наклали ви.",
    ["Show player titles in the game world."] = "Показувати титули гравців у ігровому світі.",
    ["Show players' guild names in the game world."] = "Показувати назви гільдій гравців у ігровому світі.",
    ["Show players' guild titles in the game world."] = "Показувати гільдійні звання гравців у ігровому світі.",
    ["Show spell damage caused by your pet."] = "Показувати шкоду від заклять, завдану вашим улюбленцем.",
    ["Show the name of the spell on the cast bar on nameplates."] = "Показувати назву закляття на смузі прочитання на табличках імен.",
    ["Show the portraits of the pets belonging to the enemy arena team."] = "Показувати портрети улюбленців ворожої команди на арені.",
    ["Show the portraits of your party members' pets."] = "Показувати портрети улюбленців членів вашої групи.",
    ["Show the range of raid members when they are far away by fading out their health bars."] = "Показувати віддаленість членів рейду, коли вони далеко, притлумлюючи їхні смуги здоров'я.",
    ["Show the spell that your current target is casting."] = "Показувати закляття, яке творить ваша поточна ціль.",
    ["Show the spells that players on the enemy arena team are casting."] = "Показувати закляття, які творять гравці ворожої команди на арені.",
    ["Shows a message when an aura fades from the player."] = "Показує повідомлення, коли з гравця зникає аура.",
    ["Shows a message when the player gains or loses an aura."] = "Показує повідомлення, коли гравець отримує або втрачає ауру.",
    ["Shows a message when the player gains or loses reputation with a faction."] = "Показує повідомлення, коли гравець здобуває або втрачає репутацію з фракцією.",
    ["Shows a message when you enter or leave combat."] = "Показує повідомлення, коли ви вступаєте в бій або виходите з нього.",
    ["Shows a message when you enter or leave combat. "] = "Показує повідомлення, коли ви входите в бій або виходите з нього. ",
    ["Shows a message when you gain a shield."] = "Показує повідомлення, коли ви отримуєте щит.",
    ["Shows a screen edge flash when you have a fullscreen UI up and you are in combat."] = "Показує спалах по краях екрана, коли у вас відкрито повноекранний інтерфейс і ви перебуваєте в бою.",
    ["Shows all instant gains of mana, rage, energy, and chi."] = "Показує всі миттєві поповнення мани, люті, енергії та чі.",
    ["Shows all periodic gains of mana, rage, and energy."] = "Показує всі періодичні поповнення мани, люті та енергії.",
    ["Shows an alert in the middle of the screen when you lose control of your character."] = "Показує сповіщення посеред екрана, коли ви втрачаєте контроль над своїм персонажем.",
    ["Shows attacks against you that dodge, parry, or miss."] = "Показує атаки проти вас, які ухилено, відбито або які схибили.",
    ["Shows bubbles of text above the head of the speaker."] = "Показує балабки з текстом над головою мовця.",
    ["Shows chat bubbles for instance and raid chat."] = "Показує балабки для чату підземелля та рейду.",
    ["Shows chat bubbles for party chat."] = "Показує балабки для чату групи.",
    ["Shows error messages related to UI functionality."] = "Показує повідомлення про помилки, пов'язані з роботою інтерфейсу.",
