    ["Use UI Scale"] = "Масштаб інтерфейсу",
    ["Use Verbose Mode"] = "Докладний режим",
    ["Use a larger nameplate style."] = "Використовувати більший стиль таблички імен.",
    ["Use mouse clicks to move your character to destinations."] = "Використовувати кліки миші, щоб переміщати вашого персонажа до місць призначення.",
    ["Use special reagents to enhance the weapons you create."] = "Використовуй особливі реагенти, щоб посилювати зброю, яку створюєш.",
    ["Use the \"ALT\" key to Loot when \"Auto Loot\" is checked, and to Auto Loot when it is not."] = "Використовувати клавішу \"ALT\" для звичайного збору здобичі, коли увімкнено \"Автозбір\", і для автозбору, коли його вимкнено.",
    ["Use the \"ALT\" key to cast friendly target spells on yourself even if an enemy is targeted, or there is no target."] = "Використовувати клавішу \"ALT\", щоб творити закляття на дружні цілі на собі, навіть коли вибрано ворога чи цілі немає.",
    ["Use the \"ALT\" key to cast targeted spells on your Focus Target."] = "Використовувати клавішу \"ALT\", щоб творити націлені закляття на вашу фокусну ціль.",
    ["Use the \"ALT\" key to cast targeted spells on your Mouseover Target."] = "Використовувати клавішу \"ALT\", щоб творити націлені закляття на ціль під курсором.",
    ["Use the \"ALT\" key to pick up/drag spells from locked action bars."] = "Використовувати клавішу \"ALT\", щоб брати/перетягувати закляття із заблокованих панелей дій.",
    ["Use the \"CTRL\" key to Loot when \"Auto Loot\" is checked, and to Auto Loot when it is not."] = "Натискайте клавішу \"CTRL\", щоб збирати здобич вручну, коли ввімкнено \"Автозбір здобичі\", і щоб автоматично збирати, коли його вимкнено.",
    ["Use the \"CTRL\" key to cast friendly target spells on yourself even if an enemy is targeted, or there is no target."] = "Натискайте клавішу \"CTRL\", щоб застосовувати закляття на дружні цілі на себе, навіть якщо вибрано ворога або немає цілі.",
    ["Use the \"CTRL\" key to cast targeted spells on your Focus Target."] = "Натискайте клавішу \"CTRL\", щоб застосовувати спрямовані закляття на вашу зосереджену ціль.",
    ["Use the \"CTRL\" key to cast targeted spells on your Mouseover Target."] = "Натискайте клавішу \"CTRL\", щоб застосовувати спрямовані закляття на ціль під курсором.",
    ["Use the \"CTRL\" key to pick up/drag spells from locked action bars."] = "Натискайте клавішу \"CTRL\", щоб брати чи перетягувати закляття із заблокованих панелей дій.",
    ["Use the \"SHIFT\" key to Loot when \"Auto Loot\" is checked, and to Auto Loot when it is not."] = "Натискайте клавішу \"SHIFT\", щоб збирати здобич вручну, коли ввімкнено \"Автозбір здобичі\", і щоб автоматично збирати, коли його вимкнено.",
    ["Use the \"SHIFT\" key to cast friendly target spells on yourself even if an enemy is targeted, or there is no target."] = "Натискайте клавішу \"SHIFT\", щоб застосовувати закляття на дружні цілі на себе, навіть якщо вибрано ворога або немає цілі.",
    ["Use the \"SHIFT\" key to cast targeted spells on your Focus Target."] = "Натискайте клавішу \"SHIFT\", щоб застосовувати спрямовані закляття на вашу зосереджену ціль.",
    ["Use the \"SHIFT\" key to cast targeted spells on your Mouseover Target."] = "Натискайте клавішу \"SHIFT\", щоб застосовувати спрямовані закляття на ціль під курсором.",
    ["Use the \"SHIFT\" key to pick up/drag spells from locked action bars."] = "Натискайте клавішу \"SHIFT\", щоб брати чи перетягувати закляття із заблокованих панелей дій.",
    ["Use the same gamma settings as your desktop."] = "Використовувати ті самі налаштування гами, що й на робочому столі.",
