    ["Welcome Home"] = "Ласкаво просимо додому",
    ["Welcome Home!"] = "Ласкаво просимо додому!",
    ["Well of Eternity"] = "Джерело Вічності",
    ["What is an Algari Weaverline?"] = "Що таке алґарська ткацька лінія?",
    ["What's New"] = "Що нового",
    ["What's New?"] = "Що нового?",
    ["When Target Dies"] = "Коли ціль гине",
    ["When checked the loot window will open up under the current mouse location."] = "Коли ввімкнено, вікно здобичі відкриватиметься в поточному місці курсора.",
    ["When checked your inventory will display as a single bag window"] = "Коли ввімкнено, ваш інвентар відображатиметься як одне вікно сумки",
    ["When checked, the Loot Rolls window will automatically open to show you your group members' rolls when Bind on Pickup items drop."] = "Коли ввімкнено, вікно розіграшу здобичі автоматично відкриватиметься й показуватиме розіграші учасників вашої групи, коли випадають предмети з прив'язкою при отриманні.",
    ["When enabled, highlight effects are shown strongly on the Single-Button icon and normal spell highlights are reduced. When disabled, spells show their full highlights."] = "Коли ввімкнено, ефекти підсвічування яскраво показуються на піктограмі однієї кнопки, а звичайне підсвічування заклять зменшується. Коли вимкнено, закляття показують повне підсвічування.",
    ["When held this key will allow self casting, even if an enemy is targeted."] = "Утримання цієї клавіші дозволяє застосовувати закляття на себе, навіть якщо вибрано ворога.",
    ["When held this key will enable mouseover casting."] = "Утримання цієї клавіші вмикає застосування заклять на ціль під курсором.",
    ["When pressing the ping keybind, click to contextually ping, or click and drag to trigger the ping radial menu."] = "Натиснувши клавішу позначки, клацніть для контекстної позначки або клацніть і потягніть, щоб відкрити радіальне меню позначок.",
    ["When selected you will be protected from toggling your abilities off if accidently hitting the button more than once in a short period of time."] = "Коли ввімкнено, ви будете захищені від випадкового вимкнення своїх здібностей, якщо натиснете кнопку більше одного разу за короткий час.",
    ["When this is enabled, friendly target spells that you cast while you have a non friendly target or no target will automatically be self cast."] = "Коли ввімкнено, закляття на дружні цілі, які ви застосовуєте, маючи недружню ціль або не маючи цілі, автоматично застосовуватимуться на себе.",
    ["When this setting is disabled you will only loot from the corpse you clicked on, not all the lootable corpses around you. Uncheck this to loot from all in-range lootable corpses."] = "Коли це налаштування вимкнено, ви збиратимете здобич лише з того трупа, на який клацнули, а не з усіх трупів навколо. Зніміть позначку, щоб збирати здобич з усіх трупів у межах досяжності.",
    ["When two lights are overlapping the indicator will appear."] = "Коли два джерела світла накладаються, з'явиться індикатор.",
